ValidationRule.errorConditionFormula:
OR(

/* Validation 1 : Restricted users cannot move to Claim Processed */
AND(

    NOT(
        OR(
            $Permission.Claim_user_permission_set,
            $Profile.Name = "System Administrator",
            $Profile.Name = "Corporate salesforce team",
            $Profile.Name = "Read Only"
        )
    ),

    ISCHANGED(Status__c),
    ISPICKVAL(Status__c, "Claim Processed")
)

)
